package servers_test

// L756J (THROWAWAY ab/l756j-diag-20261120, not for merge): the registry columns of the CLOSING lane of #756 (servers/l756j_arms.go, generated by l756j-gen.py): celeris MAIN fe2b5be71ebc only (module servers/celeris, the new FINAL,
// celeris#1310 merged: the opt-in Config.GCPercent), arms oe / oe2 (the option, epoll-h1-sync), oi / oi2 (iouring-h1-sync), oa / oa2 (adaptive-h1-async), d (epoll-h1-sync, default GC), ctl (std-h1, default GC) and ctlg (std-h1,
// GOGC=400). The option arms carry PROBATORIUM_CELERIS_GC_PERCENT=400 and NEVER GOGC. The expectations are stated here, not derived from the code under test; the pin comes from servers/celeris/go.mod.

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

// arm -> the exact column env (every column also carries the sampler) and the registry base column the arm copies.
var l756jWant = map[string]map[string]string{
	"oe":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"oe2":  {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"oi":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"oi2":  {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"oa":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"oa2":  {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_CELERIS_GC_PERCENT": "400"},
	"d":    {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"ctl":  {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"ctlg": {"PROBATORIUM_SCHED_SAMPLE": "1", "GOGC": "400"},
}

var l756jBaseOf = map[string]string{
	"oe": "celeris-epoll-h1-sync", "oe2": "celeris-epoll-h1-sync", "d": "celeris-epoll-h1-sync",
	"oi": "celeris-iouring-h1-sync", "oi2": "celeris-iouring-h1-sync",
	"oa": "celeris-adaptive-h1-async", "oa2": "celeris-adaptive-h1-async",
	"ctl": "celeris-std-h1", "ctlg": "celeris-std-h1",
}

var l756jName = regexp.MustCompile(`^l756j-([0-9]{3})-r([1-5])-(oe|oe2|oi|oi2|oa|oa2|d|ctl|ctlg)-(epoll-h1-sync|iouring-h1-sync|adaptive-h1-async|std-h1)$`)
var l756jPinRe = regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`)

func l756jItoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for ; n > 0; n /= 10 {
		b = append([]byte{byte('0' + n%10)}, b...)
	}
	return string(b)
}

func l756jPin(t *testing.T, dir string) string {
	t.Helper()
	mod, err := os.ReadFile(filepath.Join(dir, "go.mod"))
	if err != nil {
		t.Fatal(err)
	}
	m := l756jPinRe.FindSubmatch(mod)
	if m == nil {
		t.Fatalf("no celeris require in %s/go.mod", dir)
	}
	return string(m[1])
}

func TestL756JColumns(t *testing.T) {
	var cols []servers.Adapter
	for n, a := range servers.Registry {
		if strings.HasPrefix(n, "l756j-") {
			cols = append(cols, a)
		}
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].Name < cols[j].Name })
	if len(cols) != 45 {
		t.Fatalf("%d l756j columns, want 45 (5 reps x 9 arms)", len(cols))
	}
	mainPin := l756jPin(t, "celeris")
	if mainPin != "v1.5.12-0.20261120120335-fe2b5be71ebc" {
		t.Fatalf("servers/celeris pins %s, want the new FINAL v1.5.12-0.20261120120335-fe2b5be71ebc", mainPin)
	}
	perRep := map[string]map[string]int{}
	for i, a := range cols {
		mm := l756jName.FindStringSubmatch(a.Name)
		if mm == nil {
			t.Fatalf("column name %q", a.Name)
		}
		seq, rep, arm, eng := mm[1], mm[2], mm[3], mm[4]
		if want := i + 1; seq != strings.Repeat("0", 3-len(l756jItoa(want)))+l756jItoa(want) {
			t.Errorf("%s: seq %s is not the sorted position %d", a.Name, seq, want)
		}
		if perRep[rep] == nil {
			perRep[rep] = map[string]int{}
		}
		perRep[rep][arm]++
		base := servers.Registry[l756jBaseOf[arm]]
		if a.Engine != eng || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language || base.Framework != "celeris" {
			t.Errorf("%s: engine / capabilities differ from its base column %s", a.Name, l756jBaseOf[arm])
		}
		if a.Framework != "celeris-l756j-"+arm || a.FrameworkVersion != mainPin {
			t.Errorf("%s: framework %s version %s, want celeris-l756j-%s / %s", a.Name, a.Framework, a.FrameworkVersion, arm, mainPin)
		}
		if gb, ok := a.Bin.(servers.GoBinary); !ok || gb.ModuleDir != "servers/celeris" {
			t.Errorf("%s: bin %#v, want module servers/celeris", a.Name, a.Bin)
		}
		want := l756jWant[arm]
		if len(a.SUTEnv) != len(want) {
			t.Errorf("%s: SUTEnv %v, want %v", a.Name, a.SUTEnv, want)
		}
		for k, v := range want {
			if a.SUTEnv[k] != v {
				t.Errorf("%s: SUTEnv[%s] = %q, want %q", a.Name, k, a.SUTEnv[k], v)
			}
		}
		if strings.HasPrefix(arm, "o") {
			if _, has := a.SUTEnv["GOGC"]; has {
				t.Errorf("%s: an option arm must not carry GOGC", a.Name)
			}
		}
		p, ok := a.RatedPlans["ws-large-echo"]
		if !ok || len(a.RatedPlans) != 1 || len(p.Fractions) != 0 || len(p.AbsoluteRPS) != 3 || p.AbsoluteRPS[0] != 8376 || p.AbsoluteRPS[1] != 16753 || p.AbsoluteRPS[2] != 25129 || p.Placeholder || p.SaturationOnly {
			t.Errorf("%s: rated plans %#v, want exactly ws-large-echo: no fractions, absolute 8376, 16753 and 25129", a.Name, a.RatedPlans)
		}
		if a.Baseline {
			t.Errorf("%s: Baseline is set", a.Name)
		}
	}
	for rep, arms := range perRep {
		if len(arms) != 9 {
			t.Errorf("rep %s has %d arms, want 9", rep, len(arms))
		}
		for arm, n := range arms {
			if n != 1 {
				t.Errorf("rep %s arm %s %d times", rep, arm, n)
			}
		}
	}
	if len(perRep) != 5 {
		t.Errorf("%d reps, want 5", len(perRep))
	}
}
